import mongoose from 'mongoose'

const todoSchema = new mongoose.Schema(
  {
    title: { type: String, required: [true, 'Title is required'], trim: true, minlength: 1, maxlength: 100 },
    completed: { type: Boolean, default: false },
    priority: { type: String, enum: ['low', 'medium', 'high'], default: 'medium' },
    dueDate: { type: Date },
  },
  { timestamps: true }
)
todoSchema.index({ title: 1 })

export default mongoose.model('Todo', todoSchema)

// ## src/controllers/todoController.js
import mongoose from 'mongoose'
import Todo from '../models/Todo.js'

const FIELDS = ['title', 'completed', 'priority', 'dueDate']
const pick = (obj = {}) => Object.fromEntries(FIELDS.filter((k) => k in obj).map((k) => [k, obj[k]]))
const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

function httpError(status, message) {
  return Object.assign(new Error(message), { status })
}
function assertId(id) {
  if (!mongoose.isValidObjectId(id)) throw httpError(400, 'Invalid todo id')
}

export const listTodos = async (req, res) => {
  const { completed, priority, search, sort = '-createdAt' } = req.query
  const page = Math.max(parseInt(req.query.page) || 1, 1)
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100)

  const filter = {}
  if (completed === 'true' || completed === 'false') filter.completed = completed === 'true'
  if (['low', 'medium', 'high'].includes(priority)) filter.priority = priority
  if (typeof search === 'string' && search.trim()) {
    filter.title = { $regex: escapeRegex(search.trim()), $options: 'i' }
  }

  const allowedSort = ['createdAt', 'dueDate', 'priority', 'title']
  const sortBy = String(sort).split(',').filter((s) => allowedSort.includes(s.replace(/^-/, ''))).join(' ') || '-createdAt'

  const [data, total] = await Promise.all([
    Todo.find(filter).sort(sortBy).skip((page - 1) * limit).limit(limit),
    Todo.countDocuments(filter),
  ])
  res.json({ data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } })
}

export const getTodo = async (req, res) => {
  assertId(req.params.id)
  const todo = await Todo.findById(req.params.id)
  if (!todo) throw httpError(404, 'Todo not found')
  res.json(todo)
}

export const createTodo = async (req, res) => {
  const todo = await Todo.create(pick(req.body))
  res.status(201).json(todo)
}

export const updateTodo = async (req, res) => {
  assertId(req.params.id)
  const todo = await Todo.findByIdAndUpdate(req.params.id, pick(req.body), {
    returnDocument: 'after',
    runValidators: true,
  })
  if (!todo) throw httpError(404, 'Todo not found')
  res.json(todo)
}

export const toggleTodo = async (req, res) => {
  assertId(req.params.id)
  const todo = await Todo.findById(req.params.id)
  if (!todo) throw httpError(404, 'Todo not found')
  todo.completed = !todo.completed
  await todo.save()
  res.json(todo)
}

export const deleteTodo = async (req, res) => {
  assertId(req.params.id)
  const todo = await Todo.findByIdAndDelete(req.params.id)
  if (!todo) throw httpError(404, 'Todo not found')
  res.status(204).end()
}

