// ## src/middleware/auth.js
import jwt from 'jsonwebtoken'
import User from '../models/User.js'
import { AppError } from '../utils/AppError.js'

export async function protect(req, res, next) {
  const [scheme, token] = (req.get('authorization') ?? '').split(' ')
  if (scheme !== 'Bearer' || !token) throw new AppError('Please log in to access this resource', 401)

  let payload
  try {
    payload = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] })
  } catch {
    throw new AppError('Invalid or expired token', 401)
  }

  const user = await User.findById(payload.sub)
  if (!user) throw new AppError('User no longer exists', 401)
  req.user = user
  next()
}

export const restrictTo = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user.role)) throw new AppError('You do not have permission to do this', 403)
  next()
}

// ## src/controllers/authController.js
import jwt from 'jsonwebtoken'
import User from '../models/User.js'
import { AppError } from '../utils/AppError.js'

const signToken = (user) =>
  jwt.sign({ sub: user.id, role: user.role }, process.env.JWT_SECRET, { expiresIn: process.env.JWT_EXPIRES_IN ?? '1d' })

const publicUser = (u) => ({ id: u.id, name: u.name, email: u.email, role: u.role })

export const register = async (req, res) => {
  const { name, email, password } = req.body ?? {}
  const user = await User.create({ name, email, password })      // role is never taken from the body
  res.status(201).json({ token: signToken(user), user: publicUser(user) })
}

export const login = async (req, res) => {
  const { email, password } = req.body ?? {}
  if (typeof email !== 'string' || typeof password !== 'string') {
    throw new AppError('Email and password are required', 400)
  }
  const user = await User.findOne({ email: email.toLowerCase() }).select('+password')
  if (!user || !(await user.matchPassword(password))) throw new AppError('Invalid email or password', 401)
  res.json({ token: signToken(user), user: publicUser(user) })
}

export const me = (req, res) => res.json({ user: publicUser(req.user) })

// ## src/controllers/postController.js
import Post from '../models/Post.js'
import Comment from '../models/Comment.js'
import { AppError } from '../utils/AppError.js'

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
const canModify = (user, post) => user.role === 'admin' || post.author.equals(user._id)

async function findBySlug(slug) {
  const post = await Post.findOne({ slug })
  if (!post) throw new AppError('Post not found', 404)
  return post
}

export const listPosts = async (req, res) => {
  const page = Math.max(parseInt(req.query.page) || 1, 1)
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 50)
  const filter = { published: true }
  if (typeof req.query.tag === 'string') filter.tags = req.query.tag.toLowerCase()
  if (typeof req.query.search === 'string' && req.query.search.trim()) {
    const rx = { $regex: escapeRegex(req.query.search.trim()), $options: 'i' }
    filter.$or = [{ title: rx }, { content: rx }]
  }

  const [data, total] = await Promise.all([
    Post.find(filter).sort('-createdAt').skip((page - 1) * limit).limit(limit)
      .select('-content').populate('author', 'name'),
    Post.countDocuments(filter),
  ])
  res.json({ data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } })
}

export const getPost = async (req, res) => {
  const post = await Post.findOne({ slug: req.params.slug }).populate('author', 'name')
  if (!post) throw new AppError('Post not found', 404)
  res.json(post)
}

export const createPost = async (req, res) => {
  const { title, content, tags, published } = req.body ?? {}
  const cleanTags = Array.isArray(tags) ? tags.map((t) => String(t).toLowerCase().trim()).filter(Boolean) : []
  const post = await Post.create({ title, content, tags: cleanTags, published, author: req.user._id })
  res.status(201).json(post)
}

export const updatePost = async (req, res) => {
  const post = await findBySlug(req.params.slug)
  if (!canModify(req.user, post)) throw new AppError('You can only edit your own posts', 403)
  for (const key of ['title', 'content', 'tags', 'published']) {
    if (key in (req.body ?? {})) post[key] = req.body[key]
  }
  await post.save()
  res.json(post)
}

export const deletePost = async (req, res) => {
  const post = await findBySlug(req.params.slug)
  if (!canModify(req.user, post)) throw new AppError('You can only delete your own posts', 403)
  await Promise.all([post.deleteOne(), Comment.deleteMany({ post: post._id })])
  res.status(204).end()
}

// ## src/controllers/commentController.js
import Post from '../models/Post.js'
import Comment from '../models/Comment.js'
import { AppError } from '../utils/AppError.js'

export const listComments = async (req, res) => {
  const post = await Post.findOne({ slug: req.params.slug })
  if (!post) throw new AppError('Post not found', 404)
  const comments = await Comment.find({ post: post._id }).sort('createdAt').populate('author', 'name')
  res.json(comments)
}

export const addComment = async (req, res) => {
  const post = await Post.findOne({ slug: req.params.slug })
  if (!post) throw new AppError('Post not found', 404)
  const comment = await Comment.create({ text: req.body?.text, post: post._id, author: req.user._id })
  res.status(201).json(comment)
}

export const deleteComment = async (req, res) => {
  const comment = await Comment.findById(req.params.id)
  if (!comment) throw new AppError('Comment not found', 404)
  if (req.user.role !== 'admin' && !comment.author.equals(req.user._id)) {
    throw new AppError('You can only delete your own comments', 403)
  }
  await comment.deleteOne()
  res.status(204).end()
}

