// ## src/middleware/auth.js
import jwt from 'jsonwebtoken'
import User from '../models/User.js'

const fail = (status, message) => Object.assign(new Error(message), { status })

export async function protect(req, res, next) {
  const [scheme, token] = (req.get('authorization') ?? '').split(' ')
  if (scheme !== 'Bearer' || !token) throw fail(401, 'Please log in')
  let payload
  try { payload = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] }) }
  catch { throw fail(401, 'Invalid or expired token') }
  const user = await User.findById(payload.sub)
  if (!user) throw fail(401, 'User no longer exists')
  req.user = user
  next()
}

export const adminOnly = (req, res, next) => {
  if (req.user.role !== 'admin') throw fail(403, 'Admin access required')
  next()
}

