// ## src/controllers/productController.js
import mongoose from 'mongoose'
import Product from '../models/Product.js'

const FIELDS = ['name', 'description', 'price', 'stock', 'category']
const pick = (o = {}) => Object.fromEntries(FIELDS.filter((k) => k in o).map((k) => [k, o[k]]))
const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
const notFound = () => Object.assign(new Error('Product not found'), { status: 404 })

export const listProducts = async (req, res) => {
  const { category, search, minPrice, maxPrice, sort = '-createdAt' } = req.query
  const page = Math.max(parseInt(req.query.page) || 1, 1)
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 12, 1), 100)

  const filter = {}
  if (typeof category === 'string') filter.category = category
  if (typeof search === 'string' && search.trim()) filter.name = { $regex: escapeRegex(search.trim()), $options: 'i' }
  if (minPrice || maxPrice) {
    filter.price = {}
    if (minPrice) filter.price.$gte = Number(minPrice)
    if (maxPrice) filter.price.$lte = Number(maxPrice)
  }
  const sortBy = String(sort).split(',').filter((s) => ['price', 'name', 'createdAt'].includes(s.replace(/^-/, ''))).join(' ') || '-createdAt'

  const [data, total] = await Promise.all([
    Product.find(filter).sort(sortBy).skip((page - 1) * limit).limit(limit),
    Product.countDocuments(filter),
  ])
  res.json({ data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } })
}

export const getProduct = async (req, res) => {
  if (!mongoose.isValidObjectId(req.params.id)) throw notFound()
  const product = await Product.findById(req.params.id)
  if (!product) throw notFound()
  res.json(product)
}

export const createProduct = async (req, res) => {
  res.status(201).json(await Product.create(pick(req.body)))
}

export const updateProduct = async (req, res) => {
  if (!mongoose.isValidObjectId(req.params.id)) throw notFound()
  const product = await Product.findByIdAndUpdate(req.params.id, pick(req.body), { returnDocument: 'after', runValidators: true })
  if (!product) throw notFound()
  res.json(product)
}

