import mongoose from 'mongoose'
import Cart from '../models/Cart.js'
import Product from '../models/Product.js'

const bad = (message, status = 400) => Object.assign(new Error(message), { status })

async function getCart(userId) {
  return (await Cart.findOne({ user: userId })) ?? (await Cart.create({ user: userId, items: [] }))
}

async function present(cart) {
  await cart.populate('items.product', 'name price stock')
  const items = cart.items
    .filter((i) => i.product)
    .map((i) => ({ productId: i.product.id, name: i.product.name, price: i.product.price, qty: i.qty, lineTotal: i.product.price * i.qty }))
  return { items, total: items.reduce((sum, i) => sum + i.lineTotal, 0) }
}

export const showCart = async (req, res) => {
  res.json(await present(await getCart(req.user._id)))
}

export const addItem = async (req, res) => {
  const { productId, qty = 1 } = req.body ?? {}
  if (!mongoose.isValidObjectId(productId)) throw bad('Invalid productId')
  if (!Number.isInteger(qty) || qty < 1) throw bad('qty must be a positive integer')
  if (!(await Product.exists({ _id: productId }))) throw bad('Product not found', 404)

  const cart = await getCart(req.user._id)
  const line = cart.items.find((i) => i.product.equals(productId))
  if (line) line.qty += qty
  else cart.items.push({ product: productId, qty })
  await cart.save()
  res.status(201).json(await present(cart))
}

export const setQty = async (req, res) => {
  const { qty } = req.body ?? {}
  if (!Number.isInteger(qty) || qty < 1) throw bad('qty must be a positive integer')
  const cart = await getCart(req.user._id)
  const line = cart.items.find((i) => i.product.equals(req.params.productId))
  if (!line) throw bad('Item not in cart', 404)
  line.qty = qty
  await cart.save()
  res.json(await present(cart))
}

export const removeItem = async (req, res) => {
  const cart = await getCart(req.user._id)
  cart.items = cart.items.filter((i) => !i.product.equals(req.params.productId))
  await cart.save()
  res.json(await present(cart))
}

// ## src/controllers/orderController.js
import Cart from '../models/Cart.js'
import Product from '../models/Product.js'
import Order from '../models/Order.js'

const fail = (message, status) => Object.assign(new Error(message), { status })

export const checkout = async (req, res) => {
  const cart = await Cart.findOne({ user: req.user._id }).populate('items.product')
  if (!cart || cart.items.length === 0) throw fail('Your cart is empty', 400)

  const reserved = []                                   // lines whose stock we already decreased
  try {
    const lines = []
    for (const { product, qty } of cart.items) {
      if (!product) throw fail('A product in your cart no longer exists', 409)
      // atomic: only succeeds if enough stock is left at this very moment
      const result = await Product.updateOne({ _id: product._id, stock: { $gte: qty } }, { $inc: { stock: -qty } })
      if (result.modifiedCount === 0) throw fail(`Not enough stock for "${product.name}"`, 409)
      reserved.push({ id: product._id, qty })
      lines.push({ product: product._id, name: product.name, price: product.price, qty })
    }
    const total = lines.reduce((sum, l) => sum + l.price * l.qty, 0)
    const order = await Order.create({ user: req.user._id, items: lines, total })

    cart.items = []
    await cart.save()
    res.status(201).json(order)
  } catch (err) {
    // compensation: give back the stock we reserved
    await Promise.all(reserved.map((r) => Product.updateOne({ _id: r.id }, { $inc: { stock: r.qty } })))
    throw err
  }
}

export const myOrders = async (req, res) => {
  res.json(await Order.find({ user: req.user._id }).sort('-createdAt'))
}

export const getOrder = async (req, res) => {
  const order = await Order.findById(req.params.id)
  if (!order || (order.user.toString() !== req.user.id && req.user.role !== 'admin')) {
    throw fail('Order not found', 404)                   // 404 hides other users' orders
  }
  res.json(order)
}

export const setStatus = async (req, res) => {
  const { status } = req.body ?? {}
  if (!['pending', 'shipped', 'cancelled'].includes(status)) throw fail('Invalid status', 400)
  const order = await Order.findByIdAndUpdate(req.params.id, { status }, { returnDocument: 'after' })
  if (!order) throw fail('Order not found', 404)
  res.json(order)
}

