export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)
  let status = err.status ?? 500
  let message = err.message
  if (err.name === 'ValidationError') status = 400
  if (err.type === 'entity.parse.failed') { status = 400; message = 'Malformed JSON body' }
  if (status >= 500) { console.error(err); message = 'Internal Server Error' }
  res.status(status).json({ message })
}

// ## src/controllers/linkController.js
import Link from '../models/Link.js'
import { generateCode, sha256, safeEqual } from '../utils/code.js'
import crypto from 'node:crypto'

const RESERVED = new Set(['api', 'health', 'admin', 'static'])
const CODE_PATTERN = /^[A-Za-z0-9_-]{4,32}$/
const httpError = (status, message) => Object.assign(new Error(message), { status })

function parseTarget(value) {
  if (typeof value !== 'string' || value.length > 2048) throw httpError(400, 'url is required (max 2048 characters)')
  let parsed
  try { parsed = new URL(value) } catch { throw httpError(400, 'url is not a valid URL') }
  if (!['http:', 'https:'].includes(parsed.protocol)) throw httpError(400, 'Only http and https URLs are allowed')
  return parsed.toString()
}

export const createLink = async (req, res) => {
  const { url, customCode, expiresInDays } = req.body ?? {}
  const target = parseTarget(url)

  if (customCode !== undefined) {
    if (typeof customCode !== 'string' || !CODE_PATTERN.test(customCode) || RESERVED.has(customCode.toLowerCase())) {
      throw httpError(400, 'customCode must be 4-32 letters, digits, "-" or "_" and not a reserved word')
    }
  }
  let expiresAt
  if (expiresInDays !== undefined) {
    if (!Number.isFinite(expiresInDays) || expiresInDays <= 0 || expiresInDays > 365) {
      throw httpError(400, 'expiresInDays must be between 1 and 365')
    }
    expiresAt = new Date(Date.now() + expiresInDays * 24 * 60 * 60 * 1000)
  }

  const manageToken = crypto.randomBytes(24).toString('hex')
  for (let attempt = 0; attempt < 5; attempt++) {
    const code = customCode ?? generateCode()
    try {
      const link = await Link.create({ code, url: target, manageTokenHash: sha256(manageToken), expiresAt })
      const base = process.env.BASE_URL ?? `${req.protocol}://${req.get('host')}`
      return res.status(201).json({
        code: link.code,
        shortUrl: `${base}/${link.code}`,
        url: link.url,
        expiresAt: link.expiresAt ?? null,
        manageToken,                                       // shown ONCE; only its hash is stored
      })
    } catch (err) {
      if (err.code !== 11000) throw err
      if (customCode) throw httpError(409, 'That custom code is already taken')
      // random collision: loop and try a new code
    }
  }
  throw httpError(500, 'Could not generate a unique code')
}

export const redirect = async (req, res, next) => {
  const { code } = req.params
  if (!CODE_PATTERN.test(code)) return next()                  // not one of ours -> 404 handler

  const link = await Link.findOneAndUpdate(
    { code },
    { $inc: { clicks: 1 }, $set: { lastClickedAt: new Date() } },
    { returnDocument: 'after' }
  )
  if (!link) return res.status(404).json({ message: 'Short link not found' })
  if (link.expiresAt && link.expiresAt < new Date()) return res.status(410).json({ message: 'This link has expired' })

  res.redirect(302, link.url)
}

export const stats = async (req, res) => {
  const link = await Link.findOne({ code: req.params.code })
  if (!link) throw httpError(404, 'Short link not found')
  res.json({
    code: link.code, url: link.url, clicks: link.clicks,
    createdAt: link.createdAt, lastClickedAt: link.lastClickedAt ?? null, expiresAt: link.expiresAt ?? null,
  })
}

export const removeLink = async (req, res) => {
  const link = await Link.findOne({ code: req.params.code }).select('+manageTokenHash')
  if (!link) throw httpError(404, 'Short link not found')
  const token = req.get('x-manage-token') ?? ''
  if (!safeEqual(sha256(token), link.manageTokenHash)) throw httpError(403, 'Invalid manage token')
  await link.deleteOne()
  res.status(204).end()
}

