// ## src/socket/index.js
import { Server } from 'socket.io'
import jwt from 'jsonwebtoken'
import User from '../models/User.js'
import Message from '../models/Message.js'
import { ROOM_PATTERN } from '../controllers/messageController.js'

export function initSocket(httpServer, { corsOrigin = '*' } = {}) {
  const io = new Server(httpServer, { cors: { origin: corsOrigin } })

  // authenticate every connection
  io.use(async (socket, next) => {
    try {
      const { sub } = jwt.verify(socket.handshake.auth?.token ?? '', process.env.JWT_SECRET, { algorithms: ['HS256'] })
      const user = await User.findById(sub).select('name')
      if (!user) return next(new Error('unauthorized'))
      socket.data.user = { id: user.id, name: user.name }
      next()
    } catch {
      next(new Error('unauthorized'))
    }
  })

  // unique user names currently in a room
  const usersIn = (room) => {
    const ids = io.sockets.adapter.rooms.get(room) ?? new Set()
    return [...new Set([...ids].map((id) => io.sockets.sockets.get(id)?.data.user.name).filter(Boolean))]
  }
  const broadcastUsers = (room) => io.to(room).emit('room:users', { room, users: usersIn(room) })

  io.on('connection', (socket) => {
    const { name } = socket.data.user

    socket.on('room:join', (room, ack) => {
      if (typeof room !== 'string' || !ROOM_PATTERN.test(room)) return ack?.({ ok: false, error: 'Invalid room' })
      socket.join(room)
      socket.to(room).emit('system', `${name} joined #${room}`)
      broadcastUsers(room)
      ack?.({ ok: true })
    })

    socket.on('room:leave', (room) => {
      if (typeof room !== 'string' || !socket.rooms.has(room)) return
      socket.leave(room)
      socket.to(room).emit('system', `${name} left #${room}`)
      broadcastUsers(room)
    })

    socket.on('message:send', async ({ room, text } = {}, ack) => {
      try {
        if (typeof room !== 'string' || !socket.rooms.has(room)) return ack?.({ ok: false, error: 'Join the room first' })
        const clean = typeof text === 'string' ? text.trim() : ''
        if (!clean || clean.length > 500) return ack?.({ ok: false, error: 'Message must be 1-500 characters' })

        const saved = await Message.create({ room, user: socket.data.user.id, text: clean })
        io.to(room).emit('message:new', {
          id: saved.id, room, text: saved.text, user: { name }, createdAt: saved.createdAt,
        })
        ack?.({ ok: true })
      } catch (err) {
        console.error(err)
        ack?.({ ok: false, error: 'Could not send message' })
      }
    })

    socket.on('typing', ({ room } = {}) => {
      if (typeof room === 'string' && socket.rooms.has(room)) socket.to(room).emit('typing', { room, user: name })
    })

    socket.on('disconnecting', () => {
      for (const room of socket.rooms) {
        if (room === socket.id) continue
        socket.to(room).emit('system', `${name} disconnected`)
        // presence update after this socket is gone
        setImmediate(() => broadcastUsers(room))
      }
    })
  })

  return io
}

