import crypto from 'node:crypto'

export const sha256 = (v) => crypto.createHash('sha256').update(v).digest('hex')

export function safeEqual(a, b) {
  const x = Buffer.from(a)
  const y = Buffer.from(b)
  return x.length === y.length && crypto.timingSafeEqual(x, y)
}

// ## src/utils/fileType.js
import fs from 'node:fs/promises'

const ascii = (buf, from, to) => buf.subarray(from, to).toString('ascii')

const SIGNATURES = [
  { mime: 'image/png', ext: 'png', test: (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) },
  { mime: 'image/jpeg', ext: 'jpg', test: (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { mime: 'image/gif', ext: 'gif', test: (b) => ['GIF87a', 'GIF89a'].includes(ascii(b, 0, 6)) },
  { mime: 'image/webp', ext: 'webp', test: (b) => ascii(b, 0, 4) === 'RIFF' && ascii(b, 8, 12) === 'WEBP' },
  { mime: 'application/pdf', ext: 'pdf', test: (b) => ascii(b, 0, 5) === '%PDF-' },
]

// reads only the first 12 bytes of the file on disk
export async function detectType(filePath) {
  const handle = await fs.open(filePath, 'r')
  try {
    const buf = Buffer.alloc(12)
    await handle.read(buf, 0, 12, 0)
    return SIGNATURES.find((s) => s.test(buf)) ?? null
  } finally {
    await handle.close()
  }
}

