import { sha256, safeEqual } from '../utils/security.js'

const keys = () => (process.env.API_KEYS ?? '').split(',').map((k) => k.trim()).filter(Boolean)

export function apiKeyAuth(req, res, next) {
  const supplied = req.get('x-api-key') ?? ''
  const match = keys().find((k) => safeEqual(k, supplied))
  if (!match) return res.status(401).json({ message: 'Missing or invalid API key' })
  req.owner = sha256(match).slice(0, 16)            // stable owner id, the key itself is never stored
  next()
}

