// ## src/middleware/errorHandler.js
import multer from 'multer'

export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)

  if (err instanceof multer.MulterError) {
    const map = {
      LIMIT_FILE_SIZE: [413, 'File too large (max 5 MB)'],
      LIMIT_FILE_COUNT: [413, 'Too many files (max 5)'],
      LIMIT_UNEXPECTED_FILE: [400, 'Use the form field name "files"'],
    }
    const [status, message] = map[err.code] ?? [400, err.message]
    return res.status(status).json({ message })
  }

  let status = err.status ?? 500
  let message = err.message
  if (err.name === 'CastError') { status = 404; message = 'File not found' }
  if (status >= 500) { console.error(err); message = 'Internal Server Error' }
  res.status(status).json({ message })
}

// ## src/controllers/fileController.js
import fs from 'node:fs/promises'
import path from 'node:path'
import mongoose from 'mongoose'
import StoredFile from '../models/StoredFile.js'
import { detectType } from '../utils/fileType.js'
import { UPLOAD_DIR } from '../middleware/upload.js'

const QUOTA_BYTES = 20 * 1024 * 1024
const notFound = () => Object.assign(new Error('File not found'), { status: 404 })

const cleanName = (name) =>
  path.basename(name).replace(/[^\w.\- ()]/g, '_').slice(0, 100) || 'file'

const view = (f) => ({
  id: f.id, name: f.originalName, mime: f.mime, size: f.size, createdAt: f.createdAt,
  url: `/api/files/${f.id}/content`, downloadUrl: `/api/files/${f.id}/download`,
})

async function usedBytes(owner) {
  const [row] = await StoredFile.aggregate([
    { $match: { owner } },
    { $group: { _id: null, total: { $sum: '$size' } } },
  ])
  return row?.total ?? 0
}

async function findOwned(req) {
  const { id } = req.params
  const file = mongoose.isValidObjectId(id) ? await StoredFile.findOne({ _id: id, owner: req.owner }) : null
  if (!file) throw notFound()
  return file
}

export const uploadFiles = async (req, res) => {
  const files = req.files ?? []
  if (files.length === 0) throw Object.assign(new Error('No files uploaded (field name: files)'), { status: 400 })

  let used = await usedBytes(req.owner)
  const saved = []
  const rejected = []

  for (const f of files) {
    const original = cleanName(f.originalname)
    const type = await detectType(f.path)
    if (!type) {
      await fs.rm(f.path, { force: true })
      rejected.push({ name: original, reason: 'Unsupported or corrupted file type' })
      continue
    }
    if (used + f.size > QUOTA_BYTES) {
      await fs.rm(f.path, { force: true })
      rejected.push({ name: original, reason: 'Storage quota exceeded' })
      continue
    }
    used += f.size
    const doc = await StoredFile.create({
      owner: req.owner, originalName: original, storedName: f.filename,
      mime: type.mime, ext: type.ext, size: f.size,
    })
    saved.push(view(doc))
  }
  res.status(saved.length ? 201 : 422).json({ saved, rejected })
}

export const listFiles = async (req, res) => {
  const page = Math.max(parseInt(req.query.page) || 1, 1)
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 20, 1), 100)
  const filter = { owner: req.owner }
  const [items, total] = await Promise.all([
    StoredFile.find(filter).sort('-createdAt').skip((page - 1) * limit).limit(limit),
    StoredFile.countDocuments(filter),
  ])
  res.json({ data: items.map(view), meta: { page, limit, total, usedBytes: await usedBytes(req.owner), quotaBytes: QUOTA_BYTES } })
}

export const getFile = async (req, res) => res.json(view(await findOwned(req)))

export const content = async (req, res) => {
  const file = await findOwned(req)
  const inlineSafe = file.mime.startsWith('image/') || file.mime === 'application/pdf'
  res.set({
    'Content-Type': file.mime,                               // detected type, not client supplied
    'X-Content-Type-Options': 'nosniff',
    'Content-Disposition': inlineSafe ? 'inline' : 'attachment',
    'Cache-Control': 'private, max-age=3600',
  })
  res.sendFile(path.join(UPLOAD_DIR, file.storedName))
}

export const download = async (req, res) => {
  const file = await findOwned(req)
  res.set({ 'X-Content-Type-Options': 'nosniff', 'Content-Type': file.mime })
  res.download(path.join(UPLOAD_DIR, file.storedName), file.originalName)
}

export const removeFile = async (req, res) => {
  const file = await findOwned(req)
  await fs.rm(path.join(UPLOAD_DIR, file.storedName), { force: true })
  await file.deleteOne()
  res.status(204).end()
}

