import User from '../models/User.js'
import RefreshToken from '../models/RefreshToken.js'
import { env } from '../config/env.js'
import { randomToken, hashToken, signAccessToken } from '../utils/tokens.js'
import { sendMail } from '../utils/mailer.js'

const DAY = 24 * 60 * 60 * 1000
const COOKIE = 'rt'
const cookieOptions = {
  httpOnly: true,
  secure: env.NODE_ENV === 'production',
  sameSite: env.CROSS_SITE_COOKIES === 'true' ? 'none' : 'lax',
  path: '/api/auth',
  maxAge: env.REFRESH_TTL_DAYS * DAY,
}
const fail = (status, message) => Object.assign(new Error(message), { status })

async function startSession(req, res, user) {
  const raw = randomToken(40)
  await RefreshToken.create({
    user: user._id,
    tokenHash: hashToken(raw),
    userAgent: req.get('user-agent')?.slice(0, 200),
    expiresAt: new Date(Date.now() + env.REFRESH_TTL_DAYS * DAY),
  })
  res.cookie(COOKIE, raw, cookieOptions)
  return { accessToken: signAccessToken(user), user }
}

export const register = async (req, res) => {
  const { name, email, password } = req.validated.body
  const user = new User({ name, email, password })
  const token = randomToken()
  user.emailTokenHash = hashToken(token)
  user.emailTokenExpires = new Date(Date.now() + DAY)
  await user.save()

  await sendMail({
    to: email,
    subject: 'Verify your email',
    text: `Welcome ${name}! Verify your email (valid 24h): ${env.CLIENT_URL}/verify-email?token=${token}`,
  })
  res.status(201).json({ message: 'Registered. Please check your email to verify your account.' })
}

export const verifyEmail = async (req, res) => {
  const user = await User.findOne({
    emailTokenHash: hashToken(req.validated.body.token),
    emailTokenExpires: { $gt: new Date() },
  })
  if (!user) throw fail(400, 'Verification link is invalid or expired')
  user.isVerified = true
  user.emailTokenHash = undefined
  user.emailTokenExpires = undefined
  await user.save()
  res.json({ message: 'Email verified. You can log in now.' })
}

export const login = async (req, res) => {
  const { email, password } = req.validated.body
  const user = await User.findOne({ email }).select('+password')
  if (!user || !(await user.matchPassword(password))) throw fail(401, 'Invalid email or password')
  if (!user.isVerified) throw fail(403, 'Please verify your email before logging in')
  res.json(await startSession(req, res, user))
}

export const refresh = async (req, res) => {
  const raw = req.cookies?.[COOKIE]
  if (!raw) throw fail(401, 'No session')

  // atomic: a token can be exchanged only once (rotation)
  const stored = await RefreshToken.findOneAndDelete({ tokenHash: hashToken(raw), expiresAt: { $gt: new Date() } })
  if (!stored) {
    res.clearCookie(COOKIE, { ...cookieOptions, maxAge: undefined })
    throw fail(401, 'Session expired, please log in again')
  }
  const user = await User.findById(stored.user)
  if (!user) throw fail(401, 'User no longer exists')
  res.json(await startSession(req, res, user))
}

export const logout = async (req, res) => {
  const raw = req.cookies?.[COOKIE]
  if (raw) await RefreshToken.deleteOne({ tokenHash: hashToken(raw) })
  res.clearCookie(COOKIE, { ...cookieOptions, maxAge: undefined })
  res.status(204).end()
}

export const forgotPassword = async (req, res) => {
  const user = await User.findOne({ email: req.validated.body.email })
  if (user) {
    const token = randomToken()
    user.resetTokenHash = hashToken(token)
    user.resetTokenExpires = new Date(Date.now() + 60 * 60 * 1000)
    await user.save()
    await sendMail({
      to: user.email,
      subject: 'Reset your password',
      text: `Reset your password (valid 1 hour): ${env.CLIENT_URL}/reset-password?token=${token}`,
    })
  }
  res.json({ message: 'If that email exists, a reset link has been sent' })    // identical either way
}

export const resetPassword = async (req, res) => {
  const { token, password } = req.validated.body
  const user = await User.findOne({
    resetTokenHash: hashToken(token),
    resetTokenExpires: { $gt: new Date() },
  })
  if (!user) throw fail(400, 'Reset link is invalid or expired')
  user.password = password
  user.resetTokenHash = undefined
  user.resetTokenExpires = undefined
  await user.save()
  await RefreshToken.deleteMany({ user: user._id })                  // log out everywhere
  res.json({ message: 'Password updated. Please log in.' })
}

