import { Router } from 'express'
import rateLimit from 'express-rate-limit'
import { validate } from './middleware/validate.js'
import { protect, restrictTo } from './middleware/auth.js'
import * as s from './schemas.js'
import * as auth from './controllers/authController.js'
import * as users from './controllers/userController.js'

const router = Router()

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 30,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { message: 'Too many requests, please try again later' },
})

router.post('/auth/register', authLimiter, validate({ body: s.registerSchema }), auth.register)
router.post('/auth/verify-email', authLimiter, validate({ body: s.tokenSchema }), auth.verifyEmail)
router.post('/auth/login', authLimiter, validate({ body: s.loginSchema }), auth.login)
router.post('/auth/refresh', auth.refresh)
router.post('/auth/logout', auth.logout)
router.post('/auth/forgot-password', authLimiter, validate({ body: s.forgotSchema }), auth.forgotPassword)
router.post('/auth/reset-password', authLimiter, validate({ body: s.resetSchema }), auth.resetPassword)

router.get('/users/me', protect, users.getMe)
router.patch('/users/me', protect, validate({ body: s.profileSchema }), users.updateMe)
router.get('/admin/users', protect, restrictTo('admin'), users.listUsers)

export default router

