import { useState } from 'react'
import { Link, useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext.jsx'

export default function Login() {
  const { login } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()
  const [form, setForm] = useState({ email: '', password: '' })
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  const onChange = (e) => setForm({ ...form, [e.target.name]: e.target.value })

  async function onSubmit(e) {
    e.preventDefault()
    setError('')
    setBusy(true)
    try {
      await login(form.email, form.password)
      navigate(location.state?.from?.pathname ?? '/dashboard', { replace: true })
    } catch (err) {
      setError(err.response?.data?.message ?? 'Login failed')
    } finally {
      setBusy(false)
    }
  }

  return (
    <form onSubmit={onSubmit}>
      <h1>Login</h1>
      {error && <p role="alert" style={{ color: 'crimson' }}>{error}</p>}
      <input name="email" type="email" placeholder="Email" value={form.email} onChange={onChange} required />
      <input name="password" type="password" placeholder="Password" value={form.password} onChange={onChange} required />
      <button disabled={busy}>{busy ? 'Signing in...' : 'Login'}</button>
      <p>No account? <Link to="/register">Register</Link></p>
    </form>
  )
}

// ## src/pages/Register.jsx
import { useState } from 'react'
import { api } from '../api/client.js'

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '' })
  const [message, setMessage] = useState('')
  const [errors, setErrors] = useState([])

  const onChange = (e) => setForm({ ...form, [e.target.name]: e.target.value })

  async function onSubmit(e) {
    e.preventDefault()
    setErrors([])
    try {
      const { data } = await api.post('/auth/register', form)
      setMessage(data.message)
    } catch (err) {
      const data = err.response?.data
      setErrors(data?.errors?.map((x) => `${x.field}: ${x.message}`) ?? [data?.message ?? 'Registration failed'])
    }
  }

  if (message) return <p>{message}</p>
  return (
    <form onSubmit={onSubmit}>
      <h1>Create account</h1>
      <ul role="alert">{errors.map((e) => <li key={e}>{e}</li>)}</ul>
      <input name="name" placeholder="Name" value={form.name} onChange={onChange} required />
      <input name="email" type="email" placeholder="Email" value={form.email} onChange={onChange} required />
      <input name="password" type="password" placeholder="Password (8+ chars)" value={form.password} onChange={onChange} required />
      <button>Register</button>
    </form>
  )
}

